import math

def calculate_expression(m, n, alpha):
    """Calculates m*ceil(n*alpha) - n*floor(m*alpha)"""
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha)

alpha = math.sqrt(2)
print(f"Testing pairs (m, n) for alpha = {alpha}")
print("-" * 40)

results = {}
for m in range(1, 6):
    for n in range(1, 6):
        if m == 1 and n == 1:
            # Skip (1, 1) for initial check if needed, though it's valid.
            pass
        result = calculate_expression(m, n, alpha)
        key = (m, n)
        results[key] = result
        print(f"E({m}, {n}) = {result}")

print("-" * 40)
print("Summary of results:")
print(results)
